    ///
    /// 実際に展開できる巨大画像をテストで作ると数 GB のメモリが必要になるため、
    /// IHDR に大きな幅・高さを書いた PNG を手で組み立てる。
    static func pngHeader(width: UInt32, height: UInt32) -> Data {
        func chunk(_ type: String, _ body: Data) -> Data {
            var out = Data()
            out.append(contentsOf: withUnsafeBytes(of: UInt32(body.count).bigEndian, Array.init))
            let typeAndBody = Data(type.utf8) + body
            out.append(typeAndBody)
            out.append(contentsOf: withUnsafeBytes(of: CardExportImportService.crc32(typeAndBody).bigEndian, Array.init))
            return out
        }
        var ihdr = Data()
        ihdr.append(contentsOf: withUnsafeBytes(of: width.bigEndian, Array.init))
        ihdr.append(contentsOf: withUnsafeBytes(of: height.bigEndian, Array.init))
